/**
 * NOVA_ATELIER_WORLD — "AS FEATURED IN" brand-mark wall (revised)
 * 1. COMPOSITION: one graded backdrop plane (z=-2.6, 7x6) behind a subtle dark radial glow
 *    (z=-1.2) behind the 3x2 tile grid (3.5x1.49, gap 0.25) centered at origin; kicker text sits
 *    0.3 units above the grid top edge; each tile carries a flat monochrome wordmark on its face.
 * 2. LIGHT RIG: the host scene already supplies ambient 0.6 + key 1.2 — we add ONLY a single rim
 *    directional (#ffffff @0.9) from behind-above for the anisotropic sweep, plus a small accent
 *    point light (#ff2a38 @0.35) grazing the focal tile edge. Combined added intensity stays <=1.5
 *    to avoid stacking into a blown-white wash.
 * 3. MATERIALS: MeshPhysicalNodeMaterial per tile — roughness 0.55, metalness 0.5, clearcoat 0.2,
 *    anisotropy 0.6 aligned to x, vertical TSL color-node ramp #1a1a22->#121218 (built with tsl
 *    color() nodes, never raw hex-to-white fallbacks); a slightly larger matte backing box gives a
 *    chamfered-edge read. Backdrop/glow use unlit MeshBasicNodeMaterial.
 * 4. MOTION: mount = stagger-cards fade-up — group.position.y settles 0.2->0 while a per-tile
 *    "reveal" uniform drives colorNode brightness 0->1 (no alpha-blend sorting artifacts), 500ms
 *    power2.out, 80ms stagger, top row left-to-right first. Hover = wordmark opacity 0.78->1.0 +
 *    tile z 0->0.05 over 160ms. All timelines tracked and killed in cleanup.
 * 5. FOCAL ELEMENT: the top-center tile ("MONOCLE") carries the single emissive lift (capped low)
 *    and sits at the accent-light graze point — the one brightest read on the wall.
 */

import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, smoothstep, float, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new THREE.Group();
  root.name = 'nova-brand-mark-wall';

  const colors = config?.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#121218' }]
  };

  const disposables = { geometries: [], materials: [] };
  const timelines = [];

  // ---------------------------------------------------------------
  // DEPTH PLANE 1: graded backdrop (never flat void) — uses tsl color() nodes
  // ---------------------------------------------------------------
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#121218' }];
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const gTop = color(stops[0].hex);
  const gBottom = color(stops[1].hex);
  backdropMat.colorNode = mix(gTop, gBottom, float(1.0).sub(uv().y));
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.6);
  root.add(backdrop);
  disposables.geometries.push(backdropGeo);
  disposables.materials.push(backdropMat);

  // ---------------------------------------------------------------
  // DEPTH PLANE 2: soft dark radial glow behind the grid (atmosphere, not brightness)
  // ---------------------------------------------------------------
  const glowGeo = new THREE.PlaneGeometry(4.2, 2.5);
  const glowMat = new MeshBasicNodeMaterial();
  glowMat.colorNode = color(colors.surface);
  const d = uv().sub(0.5).length();
  glowMat.opacityNode = float(1.0).sub(smoothstep(0.1, 0.6, d)).mul(0.35);
  glowMat.transparent = true;
  glowMat.depthWrite = false;
  const glow = new THREE.Mesh(glowGeo, glowMat);
  glow.position.set(0, 0, -1.2);
  root.add(glow);
  disposables.geometries.push(glowGeo);
  disposables.materials.push(glowMat);

  // ---------------------------------------------------------------
  // LIGHT RIG — scene already provides ambient 0.6 + key 1.2; add ONLY rim + accent, capped low
  // ---------------------------------------------------------------
  const rim = new THREE.DirectionalLight(new THREE.Color('#ffffff'), 0.9);
  rim.position.set(0.5, 2.2, -2.4);
  rim.target.position.set(0, 0.3, 0);
  root.add(rim, rim.target);

  const accentLight = new THREE.PointLight(new THREE.Color(colors.accent), 0.35, 2.6, 2.0);
  accentLight.position.set(1.0, 0.5, 0.5);
  root.add(accentLight);

  // ---------------------------------------------------------------
  // TEXT: kicker
  // ---------------------------------------------------------------
  const items = config.textContent ?? config?.intent?.visualSpec?.textContent ?? [
    { text: 'AS FEATURED IN', role: 'kicker' },
    { text: 'HODINKEE', role: 'brand-mark' },
    { text: 'MONOCLE', role: 'brand-mark' },
    { text: 'WALLPAPER', role: 'brand-mark' },
    { text: 'ESQUIRE', role: 'brand-mark' },
    { text: 'WIRED', role: 'brand-mark' },
    { text: 'FINANCIAL TIMES', role: 'brand-mark' }
  ];

  const kickerItem = items.find((i) => i.role === 'kicker') ?? { text: 'AS FEATURED IN' };
  const markItems = items.filter((i) => i.role === 'brand-mark');
  while (markItems.length < 6) markItems.push({ text: '' });

  const gridTotalW = 3.5;
  const gridTotalH = 1.49;
  const tileW = 1.0;
  const tileH = 0.62;
  const gap = 0.25;

  const kicker = ctx.fontAtlas.createText(kickerItem.text, {
    fontSize: 20,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 20 * 0.12
  });
  kicker.position.set(0, gridTotalH / 2 + 0.32, 0.02);
  kicker.traverse((c) => {
    if (c.material) {
      c.material.transparent = true;
      c.material.opacity = 0;
    }
  });
  root.add(kicker);

  // ---------------------------------------------------------------
  // TILE GRID (3 cols x 2 rows) — top row left-to-right first
  // ---------------------------------------------------------------
  const tileGroups = [];
  const focalIndex = 1; // top-center ("MONOCLE") — the single brightest element

  const gradTop = stops[0].hex;
  const gradBottom = stops[1].hex;

  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 3; col++) {
      const index = row * 3 + col;
      const x = col * (tileW + gap) - gridTotalW / 2 + tileW / 2;
      const y = row === 0 ? gridTotalH / 2 - tileH / 2 : gridTotalH / 2 - tileH / 2 - (tileH + gap);

      const tileGroup = new THREE.Group();
      tileGroup.position.set(x, y + 0.2, 0); // pre-settle offset for fade-up

      // chamfer suggestion: slightly larger matte backing panel, recessed
      const chamferGeo = new THREE.BoxGeometry(tileW + 0.03, tileH + 0.03, 0.02, 1, 1, 1);
      const chamferMat = new MeshPhysicalNodeMaterial();
      chamferMat.colorNode = color(colors.surface).mul(0.6);
      chamferMat.roughness = 0.85;
      chamferMat.metalness = 0.1;
      chamferMat.clearcoat = 0.0;
      const chamfer = new THREE.Mesh(chamferGeo, chamferMat);
      chamfer.position.z = -0.025;
      tileGroup.add(chamfer);
      disposables.geometries.push(chamferGeo);
      disposables.materials.push(chamferMat);

      // reveal uniform drives mount fade WITHOUT alpha blending (avoids sort artifacts)
      const reveal = uniform(0.0);
      const tileGeo = new THREE.BoxGeometry(tileW, tileH, 0.05, 1, 1, 1);
      const tileMat = new MeshPhysicalNodeMaterial();
      const rampColor = mix(color(gradTop), color(gradBottom), float(1.0).sub(uv().y));
      tileMat.colorNode = rampColor.mul(reveal.clamp(0.0, 1.0));
      tileMat.roughness = 0.55;
      tileMat.metalness = 0.5;
      tileMat.clearcoat = 0.2;
      tileMat.clearcoatRoughness = 0.35;
      tileMat.anisotropy = 0.6;
      tileMat.anisotropyRotation = 0.0;
      tileMat.transparent = false;

      if (index === focalIndex) {
        tileMat.emissiveNode = color(colors.paper).mul(0.12).mul(reveal.clamp(0.0, 1.0));
      }

      const tile = new THREE.Mesh(tileGeo, tileMat);
      tile.position.z = 0;
      tileGroup.add(tile);
      disposables.geometries.push(tileGeo);
      disposables.materials.push(tileMat);

      // wordmark
      const wordmark = ctx.fontAtlas.createText(markItems[index].text, {
        fontSize: 13,
        color: colors.paper,
        align: 'center',
        letterSpacingPx: 13 * 0.08
      });
      wordmark.position.set(0, 0, 0.035);
      wordmark.traverse((c) => {
        if (c.material) {
          c.material.transparent = true;
          c.material.opacity = 0;
        }
      });
      tileGroup.add(wordmark);

      // accent sliver — one tile only, kept under 10% of frame
      if (index === focalIndex) {
        const striGeo = new THREE.BoxGeometry(0.015, tileH * 0.85, 0.03);
        const striMat = new MeshPhysicalNodeMaterial();
        striMat.colorNode = color(colors.accent);
        striMat.emissiveNode = color(colors.accent).mul(0.9);
        striMat.roughness = 0.4;
        striMat.metalness = 0.2;
        const stripe = new THREE.Mesh(striGeo, striMat);
        stripe.position.set(-tileW / 2 + 0.02, 0, 0.035);
        tileGroup.add(stripe);
        disposables.geometries.push(striGeo);
        disposables.materials.push(striMat);
      }

      root.add(tileGroup);

      tileGroups.push({
        group: tileGroup,
        tile,
        tileMat,
        reveal,
        wordmark,
        baseY: y,
        index
      });

      // hover handlers attached to the raycastable mesh
      tile.userData.handlers = {
        pointerenter: () => {
          gsap.to(tile.position, { z: 0.05, duration: 0.16, ease: 'power2.out' });
          wordmark.traverse((c) => {
            if (c.material) gsap.to(c.material, { opacity: 1.0, duration: 0.16 });
          });
        },
        pointerleave: () => {
          gsap.to(tile.position, { z: 0, duration: 0.16, ease: 'power2.out' });
          wordmark.traverse((c) => {
            if (c.material) gsap.to(c.material, { opacity: 0.78, duration: 0.16 });
          });
        }
      };
    }
  }

  // ---------------------------------------------------------------
  // MOUNT MOTION: stagger-cards fade-up, top row left-to-right first
  // ---------------------------------------------------------------
  const mountTl = gsap.timeline();
  tileGroups.forEach((t, i) => {
    mountTl.to(
      t.group.position,
      { y: t.baseY, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
    mountTl.to(
      t.reveal,
      { value: 1, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
    t.wordmark.traverse((c) => {
      if (c.material) {
        mountTl.to(c.material, { opacity: 0.78, duration: 0.5, ease: 'power2.out' }, i * 0.08);
      }
    });
  });
  timelines.push(mountTl);

  const kickerTl = gsap.timeline();
  kicker.traverse((c) => {
    if (c.material) {
      kickerTl.to(c.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
    }
  });
  timelines.push(kickerTl);

  // ---------------------------------------------------------------
  // root-level generic handlers (defensive aggregate)
  // ---------------------------------------------------------------
  root.userData.handlers = {
    pointerenter: () => {},
    pointerleave: () => {}
  };

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.geometries.forEach((g) => g.dispose());
    disposables.materials.forEach((m) => m.dispose());
    root.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose?.();
        if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose?.());
        else obj.material?.dispose?.();
      }
    });
  };

  return root;
}

